// Original lessons arranged by the confirmed Belonosov 2014/2015 syllabus.
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(title,body,formula)=>({title,body:body.split('\n').map(p=>'<p>'+esc(p)+'</p>').join(''),formula});
const ex=(title,statement,steps,result)=>({title,statement,steps,result});
const c=(id,title,program,semester,symbol,theory,workedExamples,deep,takeaway)=>({id,title,program,semester,symbol,theory,workedExamples,deep,takeaway,subtitle:theory.slice(0,4).map(x=>x.title).join('. ')+'.',card:title,foundation:true,summaryFormula:theory[0].formula,sources:[['Программа В. С. Белоносова, 2014/2015: архивная копия','https://studfile.net/preview/6307749/']]});
export const FOUNDATION_CHAPTERS=[
c('real','Вещественные числа и точные грани','I',1,'sup A · inf A',[
t('Рациональные числа и упорядоченное поле','Рациональное число представляется дробью p/q, где p∈ℤ, q∈ℕ; равные дроби отождествляются. Сложение и умножение коммутативны и ассоциативны, умножение дистрибутивно относительно сложения; существуют 0 и 1, противоположное каждому числу и обратное каждому ненулевому числу. Порядок согласован с действиями: прибавление одного числа сохраняет неравенство, произведение положительных чисел положительно. Поле ℚ не полно: не всякое непустое ограниченное сверху подмножество ℚ имеет точную верхнюю грань в ℚ.','p/q + r/s = (ps+rq)/(qs)'),
t('Вещественные числа и десятичная запись','Вещественные числа образуют полное упорядоченное поле ℝ, содержащее ℚ. Числа ℝ∖ℚ называются иррациональными. Неотрицательное вещественное число можно задавать бесконечной десятичной записью; конечные десятичные приближения снизу определяют его как свою точную верхнюю грань. Запись не всегда единственна: 0,999…=1. При канонической записи исключают бесконечный хвост девяток. Рациональные числа имеют конечную или периодическую десятичную запись, иррациональные — непериодическую.','ℚ ⊂ ℝ; 0,999… = 1'),
t('Верхняя и нижняя грани множества','Множество A⊆ℝ ограничено сверху, если существует M∈ℝ с x≤M для всех x∈A. Каждое такое M — верхняя грань. Нижняя грань m удовлетворяет m≤x для всех x∈A. Ограниченность означает оба условия. Грани не обязаны принадлежать A; обычно их много. Для A=(0,1) числа 1 и 2 являются верхними гранями, 0 и −1 — нижними.','∀x∈A: m≤x≤M'),
t('Супремум: определение через два условия','Супремум sup A — наименьшая верхняя грань A. Число s является sup A тогда и только тогда, когда: 1) x≤s для каждого x∈A; 2) для каждого ε>0 существует x∈A с s−ε<x. Второе условие запрещает заменить s меньшим числом, сохранив свойство верхней грани. Например, sup(0,1)=1, но максимума у (0,1) нет. Максимум — элемент множества, не меньший всех остальных.','s=sup A ⇔ (∀x∈A x≤s) и (∀ε>0 ∃x∈A: s−ε<x)'),
t('Инфимум и минимум','Инфимум inf A — наибольшая нижняя грань. Для i=inf A выполнено i≤x для всех x∈A и для каждого ε>0 существует x∈A с x<i+ε. Если i∈A, это минимум A; иначе минимума нет. Для A={1/n:n∈ℕ, n≥1} имеем inf A=0, sup A=max A=1; минимума нет. Для пустого множества вещественные sup и inf не определяют; соглашения в расширенной прямой оговаривают отдельно.','min A существует ⇔ inf A∈A  (для непустого A, ограниченного снизу)'),
t('Полнота ℝ и отсутствие полноты ℚ','Принцип точной верхней грани: каждое непустое подмножество ℝ, ограниченное сверху, имеет вещественный супремум. Из него следует аналогичное утверждение об инфимуме, поскольку inf A=−sup(−A). В ℚ множество {q∈ℚ:q≥0, q²<2} ограничено, но не имеет рационального супремума. Его вещественный супремум √2 иррационален. Полнота — существенное отличие ℝ от ℚ, а не следствие одних аксиом упорядоченного поля.','A≠∅ и A ограничено сверху ⇒ ∃sup A∈ℝ'),
t('Сумма и произведение положительных чисел через приближения','Для неотрицательных вещественных x,y их действия можно восстанавливать по рациональным приближениям снизу: x+y=sup{p+q:0≤p≤x, 0≤q≤y, p,q∈ℚ}; xy=sup{pq:0≤p≤x, 0≤q≤y, p,q∈ℚ}. Общий случай сводится к этому правилами знаков. Дистрибутивность, например, проверяют двусторонними оценками через сколь угодно точные рациональные приближения; одного формального обозначения sup для доказательства аксиом недостаточно.','xy = sup{pq: p,q∈ℚ, 0≤p≤x, 0≤q≤y} при x,y≥0'),
t('Свойство Архимеда и плотность','Для каждого x∈ℝ существует n∈ℕ с n>x. Эквивалентно: для каждого ε>0 существует n с 1/n<ε. Между любыми a<b существуют рациональное и иррациональное числа. Для рационального выбирают n с n(b−a)>1 и целое m с na<m<nb; возможный граничный случай устраняется выбором m=⌊na⌋+1. Для иррационального можно применить плотность рациональных к (a−√2,b−√2), затем прибавить √2.','a<b ⇒ ∃q∈ℚ: a<q<b'),
t('Счётность и несчётность','Множество называется счётным, если между ним и ℕ существует биекция; конечное или счётное множество называют не более чем счётным. Бесконечное подмножество счётного множества счётно: его элементы перечисляют по возрастающим номерам. ℕ×ℕ перечисляется по диагоналям. Поэтому счётное объединение не более чем счётных множеств не более чем счётно; ℚ счётно как образ пар целых чисел и положительных знаменателей. Отрезок [0,1] несчётен: диагональное построение даёт число, отличное от каждого члена предполагаемого перечисления.','|ℚ|=|ℕ|,  |[0,1]|>|ℕ|')],
[ex('Грань и максимум','A={1−1/n:n=1,2,…}. Найти sup, inf, max и min.',['Все элементы меньше 1. Для ε>0 выбираем n>1/ε; тогда 1−1/n>1−ε.','Первый элемент 0, остальные неотрицательны. Значение 1 не принадлежит A.'],'sup A=1; inf A=min A=0; максимума нет.'),ex('Определение супремума','Доказать sup(−2,3)=3.',['Каждый элемент интервала меньше 3, поэтому 3 — верхняя грань.','Для ε>0 берём x=3−min(ε/2,1). Тогда −2<x<3 и x>3−ε.'],'Оба условия определения выполнены.'),ex('Почему √2 иррационально','Предположить √2=p/q для взаимно простых положительных p,q.',['Из p²=2q² следует чётность p: p=2k.','Тогда q²=2k², поэтому q тоже чётно. Это противоречит взаимной простоте.'],'√2∉ℚ.')],
'Доказательство свойства Архимеда из полноты. Если бы ℕ было ограничено сверху, существовало бы s=sup ℕ. Тогда s−1 не является верхней гранью: найдётся n∈ℕ с n>s−1. Но n+1>s, хотя n+1∈ℕ. Противоречие.',
'Супремум — наименьшая верхняя грань, инфимум — наибольшая нижняя. Достижимость нужна для максимума и минимума, но не для точных граней. Полнота ℝ обеспечивает существование точных граней непустых ограниченных множеств.'),

c('sequences','Предел числовой последовательности','II',1,'∀ε>0 ∃N',[
t('Последовательность и её предел','Числовая последовательность — функция ℕ→ℝ; её значение при n обозначают aₙ. Число A называется пределом, если для каждого ε>0 существует номер N, после которого все члены лежат между A−ε и A+ε. Здесь один N выбирается после ε и подходит для всех n>N. Изменение конечного числа членов не меняет предела.','aₙ→A ⇔ ∀ε>0 ∃N∈ℕ ∀n>N: |aₙ−A|<ε'),
t('Окрестности и эквивалентность определений','ε-окрестность A — интервал Uε(A)=(A−ε,A+ε). В языке окрестностей aₙ→A означает: каждая окрестность A содержит все члены последовательности, кроме, возможно, конечного числа. Для стандартных ε-окрестностей это в точности неравенство |aₙ−A|<ε; произвольная окрестность точки содержит некоторую ε-окрестность. Термин «почти все номера» здесь означает все, кроме конечного числа.','aₙ∈Uε(A) ⇔ |aₙ−A|<ε'),
t('Единственность и ограниченность','Конечный предел единственен. Всякая сходящаяся к конечному числу последовательность ограничена: хвост лежит, например, в (A−1,A+1), а конечное число оставшихся членов также ограничено. Обратное неверно: (−1)ⁿ ограничена, но не сходится. Последовательности, стремящиеся к ±∞, не называют сходящимися к конечному пределу.','aₙ→A∈ℝ ⇒ ∃M ∀n: |aₙ|≤M'),
t('Алгебра пределов и неравенства','Если aₙ→A, bₙ→B с конечными пределами, то aₙ±bₙ→A±B, aₙbₙ→AB. При B≠0 частное определено начиная с некоторого номера и стремится к A/B. Из aₙ≤bₙ начиная с некоторого номера следует A≤B. Строгое неравенство при переходе к пределу может стать равенством. Теорема о зажатой последовательности: aₙ≤cₙ≤bₙ и aₙ,bₙ→L влекут cₙ→L.','aₙ≤bₙ ⇒ lim aₙ≤lim bₙ; не обязательно строго'),
t('Бесконечно малые, большие и бесконечные пределы','Бесконечно малая последовательность стремится к 0. Условие aₙ→+∞ означает: для каждого M∈ℝ существует N, при n>N выполнено aₙ>M. Для −∞ меняется направление. Условие |aₙ|→∞ называется бесконечной большой по модулю; оно не требует одного знака. Если aₙ≠0 начиная с некоторого номера, то aₙ→0 равносильно |1/aₙ|→∞. Выражения 0·∞, ∞−∞ и 0/0 не являются готовыми правилами вычисления.','aₙ→+∞ ⇔ ∀M∈ℝ ∃N ∀n>N: aₙ>M'),
t('Монотонность и число e','Неубывающая ограниченная сверху последовательность сходится к супремуму множества своих членов. Аналогично невозрастающая, ограниченная снизу, сходится к инфимуму. Если соответствующей грани нет, монотонная последовательность стремится к бесконечности нужного знака. Последовательность (1+1/n)ⁿ возрастает и ограничена сверху; её предел обозначают e. Одна ограниченность без монотонности недостаточна.','aₙ↑, aₙ≤M ⇒ aₙ→sup{aₙ:n∈ℕ}'),
t('Вложенные отрезки','Если непустые замкнутые ограниченные отрезки [aₙ,bₙ] вложены друг в друга, их пересечение непусто. Если дополнительно bₙ−aₙ→0, в пересечении ровно одна точка. Для открытых интервалов утверждение неверно: пересечение (0,1/n) пусто. Условие ограниченности обеспечено уже первым отрезком; замкнутость не позволяет потерять граничную точку.','[aₙ₊₁,bₙ₊₁]⊆[aₙ,bₙ], bₙ−aₙ→0 ⇒ ∩[aₙ,bₙ]={c}'),
t('Фундаментальность и критерий Коши','Последовательность фундаментальна, если для каждого ε>0 найдётся N, после которого любые два члена различаются меньше чем на ε. В ℝ это равносильно существованию конечного предела. Определение не требует заранее знать предел. В ℚ эквивалентность нарушается: рациональные приближения √2 фундаментальны, но не имеют рационального предела.','∀ε>0 ∃N ∀m,n>N: |aₙ−aₘ|<ε'),
t('Подпоследовательности и Больцано — Вейерштрасс','Подпоследовательность aₙₖ получается выбором строго возрастающих натуральных индексов nₖ. Подпоследовательность сходящейся последовательности имеет тот же предел. Всякая ограниченная вещественная последовательность содержит сходящуюся подпоследовательность. Число, к которому сходится некоторая подпоследовательность, называется частичным пределом.','n₁<n₂<…; aₙ→A ⇒ aₙₖ→A'),
t('Верхний и нижний пределы','Для ограниченной aₙ положим uₙ=sup{aₖ:k≥n}, lₙ=inf{aₖ:k≥n}. Последовательность uₙ невозрастает, lₙ не убывает, обе ограничены. Их пределы называются limsup aₙ и liminf aₙ. Это соответственно наибольший и наименьший частичные пределы. Конечный предел существует тогда и только тогда, когда они совпадают. Для (−1)ⁿ получаем limsup=1 и liminf=−1.','liminf aₙ ≤ limsup aₙ; равенство ⇔ aₙ сходится')],
[ex('Выбор номера N','Доказать aₙ=2+1/n→2.',['|aₙ−2|=1/n. Для заданного ε>0 выбираем натуральный N≥1/ε.','Если n>N, то 1/n<ε. Номер зависит от ε, но не от последующего выбора n.'],'Например, при ε=0,01 подходит N=100.'),ex('Ограниченная расходящаяся последовательность','aₙ=(−1)ⁿ.',['Чётная подпоследовательность равна 1, нечётная равна −1.','Если бы существовал общий предел, обе подпоследовательности имели бы его.'],'Предела нет; два частичных предела −1 и 1.'),ex('Предел через супремум','aₙ=1−1/n.',['Последовательность возрастает и ограничена сверху числом 1.','Для каждого ε>0 существуют члены больше 1−ε. Следовательно, супремум равен 1.'],'aₙ→1.')],
'Единственность предела. Если A≠B — два предела, возьмём ε=|A−B|/3. Начиная с общего достаточно большого номера имеем |aₙ−A|<ε и |aₙ−B|<ε. Тогда |A−B|≤|A−aₙ|+|aₙ−B|<2|A−B|/3, противоречие.',
'Предел задаётся порядком кванторов: сначала ε, затем общий номер N для всех последующих n. Критерий Коши проверяет сходимость без знания предела; полнота ℝ делает этот критерий достаточным.'),

c('limits','Предел и непрерывность функции','III',1,'0<|x−a|<δ',[
t('Окрестность, предельная и изолированная точки','Для δ>0 окрестность точки a на прямой — интервал Uδ(a)=(a−δ,a+δ). Проколотая окрестность исключает саму a. Точка a предельная для D⊆ℝ, если каждая проколотая окрестность a содержит точку D. Принадлежность a множеству не обязательна. Точка a∈D изолирована, если некоторая её окрестность не содержит других точек D.','U̇δ(a)={x:0<|x−a|<δ}'),
t('Предел функции: определение ε–δ','Пусть f:D→ℝ, а a — предельная точка D. Равенство limₓ→ₐf(x)=L означает: для каждого ε>0 существует δ>0, такое что для всех x∈D из 0<|x−a|<δ следует |f(x)−L|<ε. Значение f(a), если оно задано, в это условие не входит. Требование предельности a устраняет вырожденность определения.','∀ε>0 ∃δ>0 ∀x∈D: 0<|x−a|<δ ⇒ |f(x)−L|<ε'),
t('Определение через окрестности и по Гейне','На языке окрестностей: для каждой окрестности V точки L существует окрестность U точки a с f((U∖{a})∩D)⊆V. По Гейне: для каждой последовательности xₙ∈D∖{a}, стремящейся к a, выполнено f(xₙ)→L. Эти определения эквивалентны ε–δ. Для опровержения достаточно одной подходящей последовательности, нарушающей условие; для доказательства нужны все.','xₙ→a, xₙ≠a ⇒ f(xₙ)→L для всех таких xₙ'),
t('Свойства и критерий Коши','Конечный предел единственен; функция с конечным пределом ограничена в некоторой проколотой окрестности точки. Суммы, произведения и частные с ненулевым пределом знаменателя допускают переход к пределу. Критерий Коши: конечный предел существует тогда и только тогда, когда для любого ε>0 существует δ>0, при любых x,y∈D с 0<|x−a|,|y−a|<δ выполнено |f(x)−f(y)|<ε.','|f(x)−f(y)|<ε при x,y достаточно близких к a, x,y≠a'),
t('Односторонние и бесконечные пределы','В правом пределе рассматривают x>a, в левом x<a; a должна быть соответствующей предельной точкой области. Если область содержит точки с обеих сторон сколь угодно близко к a, двусторонний конечный предел существует ровно при равенстве обоих односторонних пределов. Для x→+∞ условие 0<|x−a|<δ заменяется x>R; для f(x)→+∞ условие ошибки заменяется f(x)>M.','limₓ→ₐf=L ⇔ limₓ→ₐ₋f=limₓ→ₐ₊f=L  при наличии обеих сторон'),
t('Непрерывность в точке и композиция','Функция f:D→ℝ непрерывна в a∈D, если для любого ε>0 найдётся δ>0: x∈D, |x−a|<δ влекут |f(x)−f(a)|<ε. В предельной точке это равносильно limₓ→ₐf(x)=f(a); в изолированной точке непрерывность автоматическая. Сумма и произведение непрерывных функций непрерывны; частное — там, где знаменатель ненулевой. Для g(x)→b и f, непрерывной в b, имеем f(g(x))→f(b), если композиция определена в рассматриваемой области.','f непрерывна в a ⇔ f(xₙ)→f(a) при любых xₙ∈D, xₙ→a'),
t('Разрывы и монотонные функции','Если функция определена в точке и не непрерывна там, это точка разрыва. При конечном общем пределе, отличном от f(a), разрыв устранимый. При конечных, но различных односторонних пределах — скачок. Если хотя бы один односторонний предел не существует или бесконечен — разрыв второго рода. У монотонной функции на интервале внутренние односторонние пределы конечны; её разрывы — скачки, их не более чем счётно. Непрерывность строго монотонной функции на интервале равносильна тому, что её образ — интервал.','Скачок: f(a−),f(a+)∈ℝ,  f(a−)≠f(a+)'),
t('Теоремы Вейерштрасса и промежуточное значение','Непрерывная на [a,b] функция ограничена и достигает минимума и максимума. Непрерывная на интервале функция принимает все значения между любыми двумя своими значениями. В частности, если f(a)f(b)<0 для непрерывной на [a,b] функции, найдётся c∈(a,b) с f(c)=0. На открытом интервале экстремальные значения могут не достигаться: f(x)=x на (0,1).','f∈C([a,b]) ⇒ ∃xₘ,xₘₐₓ: f(xₘ)=min f, f(xₘₐₓ)=max f'),
t('Равномерная непрерывность и Кантор','Равномерная непрерывность на D означает, что для каждого ε>0 один δ подходит для любых двух точек x,y∈D. При обычной непрерывности δ может зависеть от выбранной точки a. Теорема Кантора: непрерывная функция на компактном отрезке равномерно непрерывна. На некомпактной области это может нарушаться: x² на ℝ непрерывна, но не равномерно непрерывна.','∀ε>0 ∃δ>0 ∀x,y∈D: |x−y|<δ ⇒ |f(x)−f(y)|<ε'),
t('Непрерывная обратная функция','Если f непрерывна и строго монотонна на интервале I, то образ J=f(I) — интервал, обратная f⁻¹:J→I существует, строго монотонна и непрерывна. Требование строгой монотонности обеспечивает инъективность; кодоменом берут именно образ. Например, квадрат на [0,+∞) имеет непрерывную обратную √y; на всей ℝ обратной к квадрату нет.','f:I→f(I), f непрерывна и строго монотонна ⇒ f⁻¹ непрерывна'),
t('Элементарные функции и замечательные пределы','Вещественную экспоненту aˣ при a>1 продолжают с рациональных степеней по непрерывности и монотонности; для 0<a<1 используют обратное основание. При a≠1 обратная к ней — logₐx, x>0. Вещественная степень xᵅ при x>0 определяется как exp(α ln x). Тригонометрические функции задают через единичную окружность; в предельных формулах угол измеряется в радианах. Обратные тригонометрические функции требуют выбора промежутка строгой монотонности.','limₓ→₀ sin x/x=1; limₓ→₀ ln(1+x)/x=1'),
t('Эквивалентности и предел экспоненты','Запись f∼g при x→a означает f/g→1 там, где отношение определено. При x→0 имеем sin x∼x, ln(1+x)∼x, eˣ−1∼x, (1+x)ᵅ−1∼αx для α≠0. Эквивалентности безопасно подставлять в произведения и отношения; при вычитании старшие члены могут сократиться, и нужен следующий порядок. Неравенство Бернулли (1+t)ⁿ≥1+nt для t≥−1 и целого n≥1 доказывается индукцией.','limₓ→₀ (1+x)¹⁄ˣ=e; limₓ→₀ (aˣ−1)/x=ln a')],
[ex('Окрестность и проколотая окрестность','a=2, δ=1/4. Выписать множества.',['Uδ(2)=(7/4,9/4). Концы не входят.','Проколотая окрестность получается удалением точки 2.'],'U̇δ(2)=(7/4,2)∪(2,9/4).'),ex('Доказательство ε–δ','Доказать limₓ→₁(2x+1)=3.',['|(2x+1)−3|=2|x−1|. Для заданного ε>0 выбираем δ=ε/2.','При 0<|x−1|<δ ошибка меньше 2δ=ε.'],'Подходит δ=ε/2.'),ex('Предел и значение','f(x)=(x²−1)/(x−1) при x≠1, f(1)=7.',['При x≠1 выражение равно x+1. Предел при x→1 равен 2.','Значение f(1)=7 отличается от предела. Для непрерывного продолжения нужно назначить f(1)=2.'],'Устранимый разрыв в 1.')],
'Эквивалентность ε–δ и Гейне. Из ε–δ сразу следует условие для любой последовательности xₙ→a. Обратно, если ε–δ нарушено, существует ε₀>0: для каждого n можно выбрать xₙ∈D с 0<|xₙ−a|<1/n и |f(xₙ)−L|≥ε₀. Тогда xₙ→a, но f(xₙ) не стремится к L. Это противоречит определению по Гейне.',
'Окрестность задаёт точное условие близости. Предел описывает значения в проколотой окрестности и не зависит от f(a); непрерывность дополнительно связывает предел со значением в самой точке.')
];
FOUNDATION_CHAPTERS.push(
c('improper','Несобственные интегралы','VIII',2,'lim ∫ f',[
t('Определение и особая точка','Если f интегрируема на каждом [a,R], то ∫ₐ⁺∞f определяется как limᴿ→∞∫ₐᴿf. Если f неограниченна около конечного b, но интегрируема на каждом [a,c], c<b, интеграл определяется пределом при c→b−. Сходимость означает конечность предела. Пределы с разных сторон внутренней особенности исследуют отдельно; их нельзя произвольно сокращать.','∫ₐᵇ f := lim꜀→ᵇ₋∫ₐᶜ f при особенности в b'),
t('Критерий Коши','Для бесконечного промежутка интеграл сходится тогда и только тогда, когда для любого ε>0 существует R₀: при R₂>R₁>R₀ выполнено |∫ᴿ₁ᴿ₂f|<ε. Для конечной особенности хвостовые пределы заменяются приближением к особой точке. Условие проверяет малость всех достаточно удалённых хвостов, а не только одной выбранной последовательности верхних пределов.','∀ε>0 ∃R₀ ∀R₂>R₁>R₀: |∫ᴿ₁ᴿ₂ f|<ε'),
t('Сравнение и степенные эталоны','Для 0≤f≤g на хвосте сходимость ∫g влечёт сходимость ∫f. Если f/g→c∈(0,+∞), неотрицательные интегралы имеют одинаковый характер сходимости. На бесконечности ∫₁⁺∞x⁻ᵖdx сходится при p>1, около нуля ∫₀¹x⁻ᵖdx — при p<1. В предельном случае p=1 появляется расходящийся логарифм.','Бесконечность: p>1; ноль: p<1'),
t('Абсолютная сходимость','Если сходится ∫|f|, исходный интеграл сходится. Это следует из |∫ᴿ₁ᴿ₂f|≤∫ᴿ₁ᴿ₂|f| и критерия Коши. Обратное неверно; интеграл может сходиться за счёт смены знака, оставаясь не абсолютно сходящимся. Для ∫₁⁺∞sin x/x интеграл модулей расходится, но исходный сходится по Дирихле.','∫|f|<∞ ⇒ ∫f сходится'),
t('Признаки Дирихле и Абеля','Достаточная версия Дирихле: если F(R)=∫ₐᴿf ограничена, а g∈C¹([a,+∞)) монотонно стремится к 0, то ∫ₐ⁺∞fg сходится. Достаточная версия Абеля: если ∫ₐ⁺∞f сходится, а g∈C¹ монотонна и ограничена, то ∫fg сходится. Оба признака выводятся интегрированием по частям; более общие версии ослабляют гладкость g.','F ограничена, g↓0 ⇒ ∫fg сходится  (при указанных условиях)'),
t('Несколько особенностей и главное значение','Если особых точек конечное число, область разбивают так, чтобы каждый интеграл имел одну особенность. Сходимость требует сходимости каждого полученного интеграла; результат не зависит от обычных промежуточных точек разбиения. Главное значение — иной, связанный предельный переход, например limε→0(∫₋₁⁻εf+∫ε¹f). Для f=1/x он равен 0, но оба односторонних интеграла расходятся.','v.p.∫₋₁¹ dx/x=0, но несобственный интеграл расходится')],
[ex('Бесконечный промежуток','∫₂⁺∞dx/x².',['До R имеем [−1/x]₂ᴿ=1/2−1/R.','Предел при R→∞ конечен.'],'Сумма 1/2.'),ex('Особенность в нуле','∫₀¹dx/√x.',['Интеграл от ε до 1 равен 2−2√ε.','При ε→0+ получаем 2; подынтегральная функция неограниченна, но интеграл сходится.'],'Сумма 2.'),ex('Условная сходимость','∫₁⁺∞sin x/x dx.',['Первообразная sin x ограниченна; 1/x монотонно стремится к 0, поэтому работает Дирихле.','На каждом [kπ+π/6,kπ+5π/6] имеем |sin x|≥1/2. Вклады ∫|sin x|/x снизу сравниваются с гармоническим рядом.'],'Сходится, но не абсолютно.')],
'Для неотрицательной f интегралы I(R)=∫ₐᴿf не убывают по R. Поэтому сходимость к конечному числу эквивалентна ограниченности I(R) сверху. Это позволяет доказывать признаки сравнения без заранее известной первообразной.',
'Особенности исследуют по отдельности. Конечное главное значение не заменяет сходимость несобственного интеграла. Проверка абсолютной сходимости часто достаточна, но не необходима.'),

c('space','Пространство ℝⁿ и его множества','IX',2,'Bᵣ(a) ⊂ ℝⁿ',[
t('Линейное пространство и базис','ℝⁿ — множество упорядоченных наборов из n вещественных координат; сложение и умножение на скаляр покоординатны. Векторы v₁,…,vₖ линейно независимы, если Σαᵢvᵢ=0 влечёт αᵢ=0 для всех i. Базис — линейно независимая система, через которую выражается любой вектор. Стандартные e₁,…,eₙ образуют базис ℝⁿ, и координаты в фиксированном базисе единственны.','x=Σᵢ₌₁ⁿxᵢeᵢ'),
t('Норма и скалярное произведение','Норма удовлетворяет: ‖x‖≥0, равенство нулю только при x=0; ‖αx‖=|α|‖x‖; ‖x+y‖≤‖x‖+‖y‖. Евклидова норма ‖x‖₂=√Σxᵢ² порождается скалярным произведением x·y=Σxᵢyᵢ. Другие нормы: ‖x‖₁=Σ|xᵢ| и ‖x‖∞=max|xᵢ|. Они дают разные расстояния, но одинаковые понятия сходимости и открытости в конечной размерности.','‖x‖∞≤‖x‖₂≤√n‖x‖∞'),
t('Шары и окрестности','Открытый шар Bᵣ(a) задаётся ‖x−a‖<r, замкнутый — ‖x−a‖≤r, r>0. Окрестность точки содержит некоторый открытый шар с центром в этой точке. Проколотый шар исключает центр. При выборе другой эквивалентной нормы форма шара может измениться, но окрестностные определения описывают ту же топологию.','Bᵣ(a)={x∈ℝⁿ:‖x−a‖<r}'),
t('Внутренние, внешние и граничные точки','Точка внутренняя для A, если некоторый шар вокруг неё содержится в A; внешняя — если некоторый шар не пересекает A. Граничная точка: любой её шар пересекает и A, и дополнение ℝⁿ∖A. Граница ∂A может включать точки самого A и точки вне него. Для открытого единичного шара граница — единичная сфера, не входящая в шар.','∂A=cl A∩cl(ℝⁿ∖A)'),
t('Открытость, замкнутость и замыкание','A открыто, если все его точки внутренние. A замкнуто, если его дополнение открыто. Объединение любого семейства открытых множеств открыто; пересечение конечного семейства открытых открыто. Для замкнутых множеств — двойственные правила. Замыкание cl A — множество точек, каждый шар которых пересекает A; это наименьшее замкнутое множество, содержащее A. Граница любого множества замкнута.','cl A=A∪A′, где A′ — множество предельных точек'),
t('Предельная и изолированная точки','Точка a предельная для A, если каждый проколотый шар вокруг неё содержит точку A. Она может не принадлежать A. Точка a∈A изолирована, если некоторый её шар не содержит других точек A. Множество замкнуто тогда и только тогда, когда содержит все свои предельные точки. Изолированная точка принадлежит замыканию, но не обязана быть предельной.','a∈A′ ⇔ ∀r>0: (Bᵣ(a)∖{a})∩A≠∅'),
t('Сходимость и фундаментальность в ℝⁿ','Последовательность xₖ сходится к a, если ‖xₖ−a‖→0. В конечномерном пространстве это равносильно сходимости каждой координаты. Фундаментальность определяется условием ‖xₖ−xₗ‖<ε для всех достаточно больших k,l. Пространство ℝⁿ полно: каждая фундаментальная последовательность сходится в ℝⁿ. Доказательство сводится к полноте каждой вещественной координаты.','xₖ→a ⇔ ∀i=1,…,n: xₖ,ᵢ→aᵢ'),
t('Компактность и открытые покрытия','Множество K компактно, если из любого его покрытия открытыми множествами можно выбрать конечное подпокрытие. В ℝⁿ это равносильно замкнутости и ограниченности — теорема Гейне — Бореля. Эквивалентно: любая последовательность в K содержит подпоследовательность, сходящуюся к точке K. В произвольных бесконечномерных нормированных пространствах замкнутости и ограниченности недостаточно.','K⊆ℝⁿ компактно ⇔ K замкнуто и ограничено'),
t('Больцано — Вейерштрасс и вложенные множества','Всякая ограниченная последовательность в ℝⁿ имеет сходящуюся подпоследовательность; сначала выбирают подпоследовательность для первой координаты, затем последовательно для остальных. Убывающая последовательность непустых замкнутых подмножеств одного компактного K имеет непустое пересечение. Если их диаметры стремятся к 0, пересечение одноточечно. Без общей компактной ограничивающей области утверждение о пересечении неверно.','F₁⊇F₂⊇…, Fₖ≠∅, Fₖ замкнуты в компактном K ⇒ ∩Fₖ≠∅')],
[ex('Нормы вектора','x=(3,−4).',['Евклидова норма √(9+16)=5.','Сумма модулей 7, максимум модулей 4.'],'‖x‖₂=5; ‖x‖₁=7; ‖x‖∞=4.'),ex('Граница и замыкание','A={(x,y):x²+y²<1}.',['Все точки A внутренние; точки с x²+y²>1 внешние.','На окружности любой шар содержит точки из A и вне A.'],'∂A={x²+y²=1}; cl A={x²+y²≤1}.'),ex('Компактность','Сравнить [0,1]² и (0,1)².',['Первое множество замкнуто и ограничено.','Во втором последовательность (1/n,1/2), n≥2, стремится к (0,1/2), не входящей в множество.'],'[0,1]² компактно, (0,1)² не компактно.')],
'Почему граница замкнута. Замыкания cl A и cl(ℝⁿ∖A) замкнуты; их пересечение также замкнуто. Точка принадлежит этому пересечению ровно тогда, когда любой её шар встречает оба множества, что и является определением границы.',
'В ℝⁿ окрестности определяются шарами. Предельность, принадлежность и граничность — разные свойства точки. Компактность в конечной размерности равносильна замкнутости и ограниченности.'),

c('continuity','Пределы и непрерывность отображений','X',2,'F:ℝⁿ→ℝᵐ',[
t('Предел отображения','Пусть F:D⊆ℝⁿ→ℝᵐ, a — предельная точка D. Предел F(x) при x→a равен L, если для любого ε>0 найдётся δ>0: x∈D, 0<‖x−a‖<δ влекут ‖F(x)−L‖<ε. Определение через окрестности и последовательности эквивалентно этому условию. В многомерном случае нужно учитывать все способы приближения к точке.','∀ε>0 ∃δ>0: 0<‖x−a‖<δ ⇒ ‖F(x)−L‖<ε'),
t('Координатные функции и критерий Коши','Если F=(F₁,…,Fₘ), предел равен L=(L₁,…,Lₘ) тогда и только тогда, когда каждая Fᵢ стремится к Lᵢ. Критерий Коши требует для каждого ε>0 малости ‖F(x)−F(y)‖ при любых двух аргументах x,y из достаточно малой проколотой окрестности a в D. Полнота ℝᵐ делает этот критерий достаточным.','lim F=L ⇔ lim Fᵢ=Lᵢ для всех i'),
t('Алгебра и композиция','Пределы конечных сумм и скалярных произведений вычисляются покомпонентно. Если G(x)→b и F непрерывна в b, композиция F(G(x)) стремится к F(b), если определена в рассматриваемой области. Для предела F при y→b без непрерывности в b нужно дополнительно контролировать аргументы G(x)=b: обычное определение предела не ограничивает значение F(b).','G(x)→b, F непрерывна в b ⇒ F(G(x))→F(b)'),
t('Двойной и повторные пределы','Двойной предел f(x,y) при (x,y)→(a,b) учитывает все направления. Повторный предел сначала фиксирует одну переменную, затем предельно изменяет другую. Если двойной предел существует и соответствующие внутренние пределы существуют при всех аргументах из проколотой окрестности, соответствующий повторный предел равен двойному. Обратное неверно: для xy/(x²+y²) оба повторных предела в (0,0) равны 0, но двойного нет, поскольку вдоль y=x значения равны 1/2.','Совпадение двух повторных пределов не доказывает существование двойного'),
t('Непрерывность и компактные множества','Непрерывность F в a∈D определяется условием ‖F(x)−F(a)‖<ε при x∈D достаточно близких к a. Эквивалентны определения через последовательности и координатные функции. Непрерывный образ компактного множества компактен. Поэтому вещественная непрерывная функция на непустом компактном K ограничена и достигает обоих экстремумов. Для отображения в ℝᵐ компактность образа также даёт ограниченность.','K компактно, F непрерывна ⇒ F(K) компактно'),
t('Равномерная непрерывность и нормы','F равномерно непрерывна на D, если один δ для данного ε подходит всем x,y∈D. Непрерывное отображение на компактном K равномерно непрерывно. В конечномерном пространстве любые две нормы эквивалентны: существуют c,C>0 с c‖x‖α≤‖x‖β≤C‖x‖α. Поэтому смена нормы не меняет сходимость и непрерывность; конкретные численные значения δ и ε могут измениться.','∀ε>0 ∃δ>0 ∀x,y∈D: ‖x−y‖<δ ⇒ ‖F(x)−F(y)‖<ε'),
t('Линейные отображения и их норма','Линейное L удовлетворяет L(αx+βy)=αLx+βLy. Любое линейное отображение между конечномерными нормированными пространствами непрерывно. Его операторная норма ‖L‖=sup{‖Lx‖:‖x‖≤1} конечна и даёт оценку ‖Lx‖≤‖L‖‖x‖. Для ненулевых пространств можно использовать единичную сферу. В бесконечной размерности линейность сама по себе непрерывности не гарантирует.','‖L‖=sup‖x‖≤1 ‖Lx‖'),
t('Матрица и композиция','В фиксированных базисах L:ℝⁿ→ℝᵐ задаётся матрицей A размера m×n; её j-й столбец — координаты L(eⱼ). Для M:ℝᵐ→ℝᵏ композиция M∘L имеет матрицу BA, где B — матрица M. Порядок существенен. Операторные нормы подчиняются ‖M∘L‖≤‖M‖‖L‖ при согласованных нормах исходного, промежуточного и конечного пространств.','[M∘L]=[M][L]; ‖ML‖≤‖M‖‖L‖')],
[ex('Два пути к точке','f(x,y)=xy/(x²+y²) вне (0,0).',['По оси y=0 получаем 0.','По прямой y=x, x≠0, получаем 1/2. Пределы различаются.'],'Двойной предел в (0,0) не существует.'),ex('Операторная норма','L(x,y)=(2x,3y), евклидова норма.',['‖L(x,y)‖²=4x²+9y²≤9(x²+y²).','При (x,y)=(0,1) равенство достигается.'],'‖L‖=3.'),ex('Предел по координатам','F(x,y)=(x+y,x²+y²) при (x,y)→(1,2).',['Обе координатные функции — многочлены, поэтому непрерывны.','Подставляем аргумент в каждую координату.'],'Предел (3,5).')],
'Непрерывный образ компакта. Пусть открытые Vα покрывают F(K). Их прообразы при непрерывном F открыты относительно K и покрывают K. Из компактности выбирается конечное подпокрытие K; соответствующие Vα покрывают F(K).',
'Для отображений предел проверяют по всем аргументам, а вычисляют также покоординатно. Компактность сохраняется непрерывным образом. Операторная норма — точная количественная оценка линейного отображения.'),
c('derivatives','Дифференцирование одной переменной','IV',1,'f′(a)=lim Δf/h',[
t('Определение производной','Пусть f определена в окрестности a. Производная f′(a) — конечный предел отношения [f(a+h)−f(a)]/h при h→0, h≠0. Геометрически это предел угловых коэффициентов секущих, то есть угловой коэффициент касательной, если предел конечен. Правая и левая производные используют h→0+ и h→0−. Обычная производная существует, когда обе односторонние производные конечны и равны.','f′(a)=limₕ→₀ [f(a+h)−f(a)]/h'),
t('Дифференциал и непрерывность','Дифференцируемость в a означает представимость приращения в виде f(a+h)−f(a)=Ah+o(h). Это равносильно существованию конечной производной, причём A=f′(a). Линейная часть df=f′(a)dx называется дифференциалом. Дифференцируемость влечёт непрерывность, обратное неверно: |x| непрерывна в 0, но имеет там правую производную 1 и левую −1.','Δf=f′(a)h+o(h); df=f′(a)dx'),
t('Правила и таблица производных','Для дифференцируемых u,v производная суммы равна u′+v′, произведения — u′v+uv′. Для частного при v(a)≠0 получаем (u′v−uv′)/v². Константа имеет производную 0. Из определения и замечательных пределов выводятся (xᵅ)′=αxᵅ⁻¹ при x>0, (aˣ)′=aˣln a при a>0, (sin x)′=cos x, (cos x)′=−sin x. Формулы tg и ctg применяются там, где соответствующие знаменатели ненулевые.','(u/v)′=(u′v−uv′)/v²; (tg x)′=1/cos²x'),
t('Сложная и обратная функции','Если u дифференцируема в a, f — в u(a), то (f∘u)′(a)=f′(u(a))u′(a). Если непрерывная строго монотонная f имеет в a ненулевую производную, обратная дифференцируема в b=f(a) и (f⁻¹)′(b)=1/f′(a). Отсюда (ln x)′=1/x, (arcsin x)′=1/√(1−x²) на (−1,1), (arccos x)′=−1/√(1−x²), (arctg x)′=1/(1+x²), (arcctg x)′=−1/(1+x²) при обычном выборе ветвей.','(f∘u)′=(f′∘u)u′; (f⁻¹)′(f(a))=1/f′(a)'),
t('Высшие производные и формула Лейбница','Производная n-го порядка определяется последовательным дифференцированием. Для n раз дифференцируемых u,v формула Лейбница выражает n-ю производную произведения через биномиальные коэффициенты. При независимом x запись dⁿf=f⁽ⁿ⁾(x)(dx)ⁿ допустима. Первый дифференциал сохраняет вид при гладкой замене x=x(t); высшие дифференциалы в общем случае получают дополнительные слагаемые.','(uv)⁽ⁿ⁾=Σₖ₌₀ⁿ C(n,k)u⁽ᵏ⁾v⁽ⁿ⁻ᵏ⁾; d²f=f″(x)(dx)²+f′(x)d²x'),
t('Локальный экстремум и теорема Ферма','Точка a — локальный минимум, если f(x)≥f(a) для всех x из некоторой окрестности a в области определения; максимум задаётся обратным неравенством. Для дифференцируемой функции во внутренней точке локального экстремума f′(a)=0. Условие необходимо, но недостаточно: у x³ производная в 0 равна нулю, экстремума нет. На границе области равенство производной нулю не требуется.','Внутренний экстремум и существующая f′(a) ⇒ f′(a)=0'),
t('Ролль и Лагранж','Пусть f непрерывна на [a,b], a<b, и дифференцируема на (a,b). Если f(a)=f(b), теорема Ролля даёт c∈(a,b) с f′(c)=0. Без равенства концов теорема Лагранжа даёт c с f(b)−f(a)=f′(c)(b−a). Непрерывность нужна на всём отрезке, производная — внутри; требовать производных на концах не нужно.','∃c∈(a,b): f′(c)=[f(b)−f(a)]/(b−a)'),
t('Коши и Дарбу','Для f,g, непрерывных на [a,b] и дифференцируемых внутри, существует c с (f(b)−f(a))g′(c)=(g(b)−g(a))f′(c). Если g′ нигде внутри не равна нулю, можно записать отношение приращений как f′(c)/g′(c). Теорема Дарбу: производная принимает все промежуточные значения между любыми двумя своими значениями, даже когда сама производная не непрерывна. Поэтому производная не может иметь разрыва типа скачка.','[f(b)−f(a)]g′(c)=[g(b)−g(a)]f′(c)'),
t('Монотонность и достаточные условия экстремума','Если f′≥0 на интервале, f не убывает; если f′>0, строго возрастает. Для дифференцируемой неубывающей функции f′≥0. Строгое возрастание не требует f′>0 в каждой точке: x³ строго возрастает, но f′(0)=0. Смена знака f′ с минуса на плюс даёт строгий минимум, с плюса на минус — максимум. Знак проверяют в проколотых односторонних окрестностях.','f′: −→+ ⇒ минимум; +→− ⇒ максимум'),
t('Символы o и O','При x→a условие f=o(g) означает f(x)/g(x)→0 там, где g≠0 в рассматриваемой проколотой окрестности. Условие f=O(g) означает существование C и окрестности, где |f|≤C|g|. Это утверждения о сравнении функций в указанном предельном переходе, а не отдельные числовые константы. Например, x²=o(x) при x→0; x²=O(x) также верно около нуля.','f=o(g) ⇒ f=O(g), но обратное в общем случае неверно'),
t('Тейлор с остатком Пеано','Если f имеет производные до порядка n в окрестности a, включая n-ю в a, то f(a+h)=Σₖ₌₀ⁿ f⁽ᵏ⁾(a)hᵏ/k!+o(hⁿ). Такая запись определяет локальное приближение и порядок остатка; она не равна бесконечному ряду Тейлора. Коэффициенты многочлена этого порядка единственны: разность двух таких многочленов не может иметь первый ненулевой коэффициент и одновременно быть o(hⁿ).','f(a+h)=f(a)+f′(a)h+…+f⁽ⁿ⁾(a)hⁿ/n!+o(hⁿ)'),
t('Остатки Лагранжа и Коши','Если f имеет непрерывные производные до порядка n на отрезке между a и x и производную порядка n+1 внутри, остаток после степени n можно записать через некоторую ξ между a и x. В форме Лагранжа Rₙ=f⁽ⁿ⁺¹⁾(ξ)(x−a)ⁿ⁺¹/(n+1)!. В форме Коши Rₙ=f⁽ⁿ⁺¹⁾(ξ)(x−ξ)ⁿ(x−a)/n!. Точки ξ в двух формулах могут различаться. Ограничение производной даёт численную оценку ошибки.','|f⁽ⁿ⁺¹⁾|≤M ⇒ |Rₙ|≤M|x−a|ⁿ⁺¹/(n+1)!'),
t('Правило Лопиталя','Достаточная локальная версия: f,g дифференцируемы в проколотой односторонней окрестности a, g′≠0, f,g→0. Если f′/g′ имеет конечный или бесконечный предел L, то f/g→L. Аналогичное правило действует для неопределённости ∞/∞ при соответствующих условиях и для бесконечного аргумента. Отношение производных рассматривают только после проверки неопределённости и гипотез. Отсутствие предела f′/g′ не доказывает отсутствия предела f/g.','0/0 или ∞/∞ и выполненные гипотезы ⇒ lim f/g=lim f′/g′'),
t('Выпуклость и точки перегиба','Функция выпукла на интервале, если f((1−t)x+ty)≤(1−t)f(x)+tf(y) при 0≤t≤1. Выпуклая конечная функция непрерывна внутри интервала и имеет конечные односторонние производные во внутренних точках; левая не превосходит правую. Для дифференцируемой f выпуклость равносильна неубыванию f′; для C²-функции — f″≥0. В точке перегиба меняется характер выпуклости; равенства f″=0 недостаточно, как показывает x⁴. График дифференцируемой выпуклой функции лежит не ниже любой своей касательной.','f(y)≥f(x)+f′(x)(y−x) для дифференцируемой выпуклой f'),
t('Неравенства выпуклости','Йенсен: для выпуклой f и весов λᵢ≥0 с суммой 1 имеем f(Σλᵢxᵢ)≤Σλᵢf(xᵢ). Юнг: ab≤aᵖ/p+bᑫ/q при a,b≥0, p,q>1, 1/p+1/q=1. Гёльдер: Σ|aᵢbᵢ|≤(Σ|aᵢ|ᵖ)¹⁄ᵖ(Σ|bᵢ|ᑫ)¹⁄ᑫ. Минковский: (Σ|aᵢ+bᵢ|ᵖ)¹⁄ᵖ≤(Σ|aᵢ|ᵖ)¹⁄ᵖ+(Σ|bᵢ|ᵖ)¹⁄ᵖ для p≥1. Здесь суммы конечные; бесконечные версии требуют сходимости.','p=q=2 в Гёльдере: |a·b|≤‖a‖₂‖b‖₂')],
[ex('Производная по определению','f(x)=x², a=1.',['При h≠0 отношение [(1+h)²−1]/h=2+h.','При h→0 получаем предел 2. Значит, df(1)=2dx.'],'f′(1)=2.'),ex('Непрерывность без производной','f(x)=|x| в 0.',['При h>0 отношение |h|/h=1.','При h<0 оно равно −1. Односторонние пределы различаются.'],'f непрерывна в 0, но f′(0) не существует.'),ex('Тейлор и сокращение главных членов','Найти limₓ→₀ (eˣ−1−x)/x².',['eˣ=1+x+x²/2+o(x²).','После вычитания 1+x числитель равен x²/2+o(x²).'],'Предел равен 1/2.')],
'Из дифференцируемости следует непрерывность: Δf=f′(a)h+o(h)→0 при h→0. В теореме Ферма при минимуме правые разностные отношения неотрицательны, левые неположительны; существующий общий предел обязан быть одновременно ≥0 и ≤0, то есть равен 0.',
'Производная — предел разностного отношения; дифференциал — линейная часть приращения. Теоремы о среднем и формула Тейлора применимы только при проверенных условиях непрерывности и дифференцируемости.'),

c('numeric','Числовые ряды','V',2,'Σ aₙ = lim Sₙ',[
t('Сумма ряда и необходимое условие','Для числовой последовательности aₙ частичная сумма Sₙ=a₁+…+aₙ. Ряд Σaₙ сходится, если Sₙ имеет конечный предел S; это число называют суммой ряда. Необходимое условие aₙ→0 следует из aₙ=Sₙ−Sₙ₋₁. Оно недостаточно: гармонический ряд Σ1/n расходится. Конечное изменение слагаемых не меняет характер сходимости.','Σₙ₌₁∞aₙ=S ⇔ Sₙ→S∈ℝ'),
t('Критерий Коши и телескопирование','Ряд сходится тогда и только тогда, когда для каждого ε>0 существует N: для любых m>n≥N выполнено |aₙ₊₁+…+aₘ|<ε. Если aₙ=bₙ−bₙ₊₁, частичная сумма телескопируется в b₁−bₙ₊₁. Если bₙ имеет конечный предел B, сумма равна b₁−B. Сокращение бесконечных выражений без перехода к конечным частичным суммам не обосновано.','Sₘ−Sₙ=Σₖ₌ₙ₊₁ᵐaₖ'),
t('Положительные ряды и сравнение','Для aₙ≥0 частичные суммы не убывают, поэтому сходимость равносильна их ограниченности. Если 0≤aₙ≤bₙ начиная с некоторого номера, сходимость Σbₙ влечёт сходимость Σaₙ. Если aₙ/bₙ→c∈(0,+∞), положительные ряды имеют одинаковый характер. Степенной ряд Σ1/nᵖ сходится ровно при p>1; для гармонического ряда группировка от 2ᵏ до 2ᵏ⁺¹−1 даёт вклады не меньше 1/2.','Σ1/nᵖ сходится ⇔ p>1'),
t('Признаки Даламбера и Коши','Если aₙ≠0 и |aₙ₊₁/aₙ|→q, при q<1 ряд сходится абсолютно, при q>1 расходится; при q=1 признак ответа не даёт. Коренной признак использует q=limsup |aₙ|¹⁄ⁿ с теми же выводами. Они сравнивают хвост с геометрической прогрессией. При q=1 возможны оба исхода: Σ1/n и Σ1/n².','q<1 ⇒ абсолютная сходимость; q>1 ⇒ расходимость'),
t('Абсолютная и условная сходимость','Ряд сходится абсолютно, если сходится Σ|aₙ|. По критерию Коши это влечёт сходимость Σaₙ. Если исходный ряд сходится, а ряд модулей расходится, сходимость условная. Абсолютно сходящийся ряд допускает любую перестановку с сохранением суммы. Для условно сходящихся вещественных рядов такого свойства нет; свободно менять порядок слагаемых нельзя.','Σ|aₙ|<∞ ⇒ Σaₙ сходится'),
t('Преобразование Абеля и признак Дирихле','Если Aₖ=Σᵢ₌₁ᵏaᵢ, то Σₖ₌₁ⁿaₖbₖ=Aₙbₙ+Σₖ₌₁ⁿ⁻¹Aₖ(bₖ−bₖ₊₁). Из этой формулы выводится признак Дирихле: если частичные суммы aₙ ограничены, а bₙ монотонно стремится к 0, ряд Σaₙbₙ сходится. В частности, знакочередующийся ряд Σ(−1)ⁿ⁻¹bₙ при bₙ≥0, bₙ↓0 сходится — признак Лейбница. Его ошибка после n членов по модулю не больше bₙ₊₁.','|S−Sₙ|≤bₙ₊₁ для ряда Лейбница'),
t('Признак Абеля','Если Σaₙ сходится, а bₙ монотонна и ограничена, то Σaₙbₙ сходится. Монотонная ограниченная bₙ имеет предел b. Можно разделить произведение на aₙ(bₙ−b) и baₙ; первый ряд исследуется по Дирихле, второй сходится по условию. Абель не требует bₙ→0, в отличие от указанной версии Дирихле.','Σaₙ сходится, bₙ монотонна и ограничена ⇒ Σaₙbₙ сходится')],
[ex('Телескопический ряд','Σₙ≥₁1/[n(n+1)].',['1/[n(n+1)]=1/n−1/(n+1).','Sₙ=1−1/(n+1)→1.'],'Сумма 1.'),ex('Условная сходимость','Σₙ≥₁(−1)ⁿ⁻¹/n.',['1/n убывает к 0; по Лейбницу ряд сходится.','Ряд модулей — гармонический, он расходится.'],'Сходимость условная.'),ex('Факториал и Даламбер','Σₙ≥₁1/n!.',['aₙ₊₁/aₙ=1/(n+1)→0.','Предельное отношение меньше 1.'],'Ряд сходится абсолютно.')],
'Гармонический ряд расходится: в блоке от n=2ᵏ до 2ᵏ⁺¹−1 имеется 2ᵏ слагаемых, каждое больше либо равно 1/2ᵏ⁺¹. Сумма каждого блока не меньше 1/2. Поэтому частичные суммы не ограничены.',
'Сходимость ряда — сходимость частичных сумм, а не отдельных слагаемых. Всегда сначала проверяют необходимое условие, затем подходящий признак; абсолютную и условную сходимость различают.'),

c('indefinite','Неопределённый интеграл','VI',2,'∫f dx = F+C',[
t('Первообразная и семейство решений','Первообразная F для f на интервале I удовлетворяет F′=f во всех точках I. Любые две первообразные на интервале отличаются постоянной. Неопределённый интеграл — семейство всех первообразных. На разных компонентах несвязной области постоянные независимы: для 1/x интервалы (−∞,0) и (0,+∞) не обязаны иметь одинаковое C.','∫f(x)dx={F(x)+C:C∈ℝ} на одном интервале'),
t('Линейность и таблица','Если у f,g есть первообразные, то у αf+βg первообразной является αF+βG. Основные формулы проверяют дифференцированием: ∫xᵖdx=xᵖ⁺¹/(p+1)+C при p≠−1 на области определения степеней; ∫dx/x=ln|x|+C на интервале без нуля; ∫eˣdx=eˣ+C; ∫cos x dx=sin x+C; ∫sin x dx=−cos x+C.','∫(αf+βg)dx=α∫f dx+β∫g dx с учётом произвольной постоянной'),
t('Подстановка','Если F′=f, а φ дифференцируема, то производная F(φ(t)) равна f(φ(t))φ′(t). Поэтому ∫f(φ(t))φ′(t)dt=F(φ(t))+C. Для представления ответа в исходной переменной при x=φ(t) нужно выбрать подходящую обратную ветвь и область. Подстановка — применение правила цепочки в обратном порядке.','∫f(φ(t))φ′(t)dt=F(φ(t))+C'),
t('Интегрирование по частям','Равенство (uv)′=u′v+uv′ даёт ∫u v′dx=uv−∫u′v dx. Выбор u полезен, если дифференцирование его упрощает. Например, у xⁿ степень снижается; у ln x производная 1/x. Если неизвестный интеграл после повторного применения появляется с обеих сторон, его можно найти из алгебраического уравнения, сохраняя общую постоянную.','∫u dv=uv−∫v du'),
t('Рациональные дроби и неопределённые коэффициенты','Неправильную рациональную дробь сначала делят на многочлен. Правильную раскладывают по вещественным линейным и неприводимым квадратным множителям знаменателя. Для (x−a)ᵐ нужны Aₖ/(x−a)ᵏ, k=1,…,m; для (x²+px+q)ᵐ нужны (Bₖx+Cₖ)/(x²+px+q)ᵏ. Коэффициенты находятся после приведения к общему знаменателю и сравнения коэффициентов тождества. Область исходной дроби сохраняют.','1/[x(x+1)]=1/x−1/(x+1)'),
t('Метод Остроградского и типовые замены','При интегрировании рациональной дроби метод Остроградского отделяет рациональную производную от дроби с квадратсвободным знаменателем: повторные полюса можно учесть в рациональной части, а оставшаяся интеграция сводится к логарифмам и арктангенсам. Для рациональных выражений от sin x и cos x универсальна подстановка t=tg(x/2) на подходящих интервалах: sin x=2t/(1+t²), cos x=(1−t²)/(1+t²), dx=2dt/(1+t²). Для корней квадратного трёхчлена применяют подстановки Эйлера с проверкой знаков и обратимости.','t=tg(x/2) ⇒ dx=2dt/(1+t²)')],
[ex('Логарифм и область','∫dx/[x(x+1)].',['Разложение: 1/[x(x+1)]=1/x−1/(x+1).','Интегрируем на каждом интервале, не пересекающем −1 и 0.'],'ln|x|−ln|x+1|+C.'),ex('Подстановка','∫2x cos(x²)dx.',['Положим u=x², du=2x dx.','∫cos u du=sin u+C.'],'sin(x²)+C.'),ex('По частям','∫ln x dx при x>0.',['u=ln x, dv=dx; du=dx/x, v=x.','x ln x−∫1 dx.'],'x ln x−x+C.')],
'Проверка ответа обязательна дифференцированием на исходной области. Например, (ln|x|−ln|x+1|)′=1/x−1/(x+1)=1/[x(x+1)] при x≠−1,0. Первообразные на трёх компонентах области могут иметь разные постоянные.',
'Неопределённый интеграл — семейство первообразных на указанном интервале. Подстановка опирается на правило цепочки, интегрирование по частям — на производную произведения; ответ проверяют производной.')
);
